 CREATE OR REPLACE FUNCTION public.getrestitutiondashboarddetails(v_pagetype character varying, v_lipagenumber bigint, v_lipagesize bigint)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
  RETURNS TABLE(totalcount bigint, restitutionpaymentflatfilecontentid uuid, restitutionpaymentflatfileid uuid, paymentnumber bigint, paymentdate character varying, depositnumber character varying, accountarea character varying, payerfirstname character varying, payerlastname character varying, payeraddress character varying, payeraddress1 character varying, memofirstname character varying, memolastname character varying, checkamt numeric, allocatedamount numeric, balanceamount numeric, documentpath character varying, paymentamount numeric, restitutionno json, victimpersondetails json, payercity character varying, payerstatekey character varying, payerzipcode character varying, restitutionstatus character varying, refundstatus character varying, refundaccounttype character varying)
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
   v_pagenumber int;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
   v_pageoffset int;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 declare searchstring character varying(1000);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 IF COALESCE(v_liPageSize, 0) < 1 THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
         v_liPageSize := 10;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
 END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 IF COALESCE(v_liPageNumber, 0) < 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
 THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
         v_liPageNumber := 1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 v_pagenumber := v_liPageNumber - 1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 v_pageoffset := v_pagenumber * v_liPageSize;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 /* select count(1) over() as totalcount,irp.intakeserreqrestitutionpaymentid,irp.intakeserreqrestitutionid,irp.paymentamount,irp.paymentnumber,irp.paymentdate,irp.paymenttype,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 irp.checknumber,irp.payerfirstname,irp.payerlastname,irp.payeraddress,irp.payercity,irp.payerstatekey,irp.payerzipcode,irp.depositnumber,irp.accountarea,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
 irp.memofirstname,irp.memolastname,irp.restitutionpaymentflatfilecontentid,json_build_object('youthpersonid',irp.youthpersonid,'youthfirstname',pp.firstname,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
   'youthlastname', pp.lastname ,'youthcjamspid', pp.cjamspid, 'youthdob',pp.dob, 'youthgendertypekey',pp.gendertypekey ) as youthpersondetails,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
    json_build_object('victimpersonid',irp.victimpersonid,'victimfirstname',pv.firstname,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
   'victimlastname', pv.lastname ,'victimcjamspid', pv.cjamspid, 'victimdob',pv.dob, 'victimgendertypekey',pv.gendertypekey ) as victimpersondetails,ir.restitutionno,coalesce(rfc.checkamt,0)-coalesce(rfc.balanceamount,0) as allocatedamount, rfc.checkamt,rfc.balanceamount,irp.restitutionstatus,rfc.documentpath                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
 from                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
   intakeserreqrestitutionpayment irp                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
      join person pp on pp.personid= irp.youthpersonid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
    join person pv on pv.personid = irp.victimpersonid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
       join intakeserreqrestitution ir on ir.intakeserreqrestitutionid = irp.intakeserreqrestitutionid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
           join restitutionpaymentflatfilecontent rfc on rfc.restitutionpaymentflatfilecontentid = irp.restitutionpaymentflatfilecontentid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
           where irp.restitutionstatus is not null                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
           and (case when v_pagetype='Payment' then rfc.balanceamount=0.00 else rfc.balanceamount!=0.00 end) */                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
  /*select count(1) over() as totalcount, rfc.restitutionpaymentflatfilecontentid , rfc.restitutionpaymentflatfileid , rfc.paymentno, rfc.asofdate,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
  rfc.lockboxno, rfc.vakaccountnumber, rfc.firstname,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
  rfc.lastname, rfc.addressline1,rfc.addressline2, rfc.customernumber, rfc.checkno, rfc.checkamt,coalesce(rfc.checkamt,0)-coalesce(rfc.balanceamount,0) as allocatedamount,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
  rfc.balanceamount, rfc.documentpath,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
 (select sum(irp.paymentamount) from intakeserreqrestitutionpayment as irp                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
  Join intakeserreqrestitution ir on ir.intakeserreqrestitutionid = irp.intakeserreqrestitutionid and ir.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
  where irp.restitutionpaymentflatfilecontentid = rfc.restitutionpaymentflatfilecontentid and irp.activeflag=1 limit 1),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
  (select json_agg(x) from (select ir.restitutionno from intakeserreqrestitution as ir                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
  JOIN intakeserreqrestitutionpayment as irp on ir.intakeserreqrestitutionid = irp.intakeserreqrestitutionid and irp.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
  where irp.restitutionpaymentflatfilecontentid = rfc.restitutionpaymentflatfilecontentid) as X ) as restitutionno,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
   (select json_agg(x) from (select ir.intakeserreqrestitutionid,ir.restitutionno,irp.youthpersonid,pp.firstname,pp.lastname,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
   pp.cjamspid, pp.dob, pp.gendertypekey from person pp                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
   join intakeserreqrestitutionpayment as irp on pp.personid= irp.victimpersonid and irp.activeflag =1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
   JOIN intakeserreqrestitution as ir on ir.intakeserreqrestitutionid = irp.intakeserreqrestitutionid and irp.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
   where irp.restitutionpaymentflatfilecontentid = rfc.restitutionpaymentflatfilecontentid) as X ) as victimpersondetails,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
   rfc.city,rfc.state,rfc.zip,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
   (select irp.restitutionstatus from intakeserreqrestitutionpayment as irp                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
  Join intakeserreqrestitution ir on ir.intakeserreqrestitutionid = irp.intakeserreqrestitutionid and ir.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
  where irp.restitutionpaymentflatfilecontentid = rfc.restitutionpaymentflatfilecontentid and irp.activeflag=1 limit 1) as status                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
  from  restitutionpaymentflatfilecontent as rfc                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
  where rfc.activeflag=1 and rfc.restitutionpaymentflatfilecontentid in(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
  select irp.restitutionpaymentflatfilecontentid from intakeserreqrestitutionpayment as irp) and (case when v_pagetype='Payment' then rfc.balanceamount=0.00 else rfc.balanceamount!=0.00 end)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
  order by rfc.paymentno asc  */                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
  IF (lower(v_pagetype) = 'payment') THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
  searchstring:=  '  AND (rfc.status=''Pending'' or rfc.status=''Approved'') order by rfc.updatedon desc,rfc.paymentno,rfc.status asc ';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
  ELSIF (lower(v_pagetype) = 'refund') THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
  searchstring:=  ' AND (rfc.status=''Pending'' or rfc.status=''Approved'') AND rfc.refundstatus is not null AND (rfc.refundstatus=''Refund Pending'' or rfc.refundstatus=''Refund Approved'') order by rfc.updatedon desc,rfc.paymentno,rfc.refundstatus,rfc.status asc';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
  END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
  return query                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
  execute                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
  'select count(1) over() as totalcount, rfc.restitutionpaymentflatfilecontentid , rfc.restitutionpaymentflatfileid , rfc.paymentno, rfc.asofdate,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
  rfc.lockboxno, rfc.vakaccountnumber, rfc.firstname,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
  rfc.lastname, rfc.addressline1,rfc.addressline2, rfc.customernumber, rfc.checkno, rfc.checkamt,coalesce(rfc.checkamt,0)-coalesce(rfc.balanceamount,0) as allocatedamount,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
  rfc.balanceamount, rfc.documentpath,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
 (select sum(irp.paymentamount) from intakeserreqrestitutionpayment as irp                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
  Join intakeserreqrestitution ir on ir.intakeserreqrestitutionid = irp.intakeserreqrestitutionid and ir.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
  where irp.restitutionpaymentflatfilecontentid = rfc.restitutionpaymentflatfilecontentid and irp.activeflag=1 limit 1),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
  (select json_agg(x) from (select ir.restitutionno from intakeserreqrestitution as ir                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
  JOIN intakeserreqrestitutionpayment as irp on ir.intakeserreqrestitutionid = irp.intakeserreqrestitutionid and irp.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
  where irp.restitutionpaymentflatfilecontentid = rfc.restitutionpaymentflatfilecontentid) as X ) as restitutionno,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
   (select json_agg(x) from (select ir.intakeserreqrestitutionid,ir.restitutionno,irp.youthpersonid,pp.firstname,pp.lastname,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
   pp.cjamspid, pp.dob, pp.gendertypekey from person pp                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
   join intakeserreqrestitutionpayment as irp on pp.personid= irp.victimpersonid and irp.activeflag =1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
   JOIN intakeserreqrestitution as ir on ir.intakeserreqrestitutionid = irp.intakeserreqrestitutionid and irp.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
   where irp.restitutionpaymentflatfilecontentid = rfc.restitutionpaymentflatfilecontentid) as X ) as victimpersondetails,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
   rfc.city,rfc.state,rfc.zip,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
   (select irp.restitutionstatus from intakeserreqrestitutionpayment as irp                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
  Join intakeserreqrestitution ir on ir.intakeserreqrestitutionid = irp.intakeserreqrestitutionid --and ir.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
  where irp.restitutionpaymentflatfilecontentid = rfc.restitutionpaymentflatfilecontentid and irp.activeflag=1 limit 1) as status,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
  rfc.refundstatus,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
  (select RF.description from referencevalues as RF JOIN referencetype as RT ON RT.referencetypeid = RF.referencetypeid and RT.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
  where RF.ref_key in (select RPFFC.overpaymentacctype from restitutionpaymentflatfilecontent as RPFFC ) and RT.referencetypeid=58)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
  from  restitutionpaymentflatfilecontent as rfc                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
  where rfc.activeflag=1 '|| searchstring ||'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
  LIMIT '|| v_liPageSize ||' OFFSET '|| v_pageoffset ||'';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             

